mapper.select:
SELECT a.id,a.video_id,a.video_name,a.start_time,a.paragraph, a.subsection_type,a.duration,a.vedio_sizie,a.end_time, a.batch_number,a.video_type,a.definition, a.storage_path,a.live_url,a.share_url,a.source_url, a.anchor_id,a.is_recording,a.source_type,a.live_title, a.analysis_status,a.analysis_time, a.error_reason,a.sec_uid,a.trade_id,a.platform_type,a.user_id,a.type, a.create_date,a.update_date,a.upload_status,a.is_mark, a.play_url,a.cloud_store,a.delete_status,a.tenant_id FROM tb_anchor_video a
INNER JOIN ( select source_id as video_id from tb_data_screenshot where source_type = 0 and screenshot_status = 3 and user_id = #{userId} and tenant_id = #{tenantId} GROUP BY source_id ) temp ON a.video_id = temp.video_id
INNER JOIN ( select video_id from tb_video_data_viewing_confuse where is_deleted = 0 and data_status = 1 and user_id = #{userId} and tenant_id = #{tenantId} GROUP BY video_id ) temp ON a.video_id = temp.video_id
WHERE a.is_deleted = 0 AND a.video_slice_type = 0 AND a.analysis_status = #{analysisStatus} AND a.sec_uid = #{secUid} AND a.user_id = #{userId} AND a.tenant_id = #{tenantId}
AND a.delete_status = 0
AND a.delete_status in (0, 1) AND a.upload_status = #{uploadStatus}
AND a.video_id <> #{videoId} AND a.duration >= 60 AND a.end_time <= #{endTime} ORDER BY a.start_time DESC LIMIT #{limit};

SELECT
av.*
FROM
tb_anchor_video av

    JOIN tb_anchor_url au on av.sec_uid = au.sec_uid and au.anchor_name like CONCAT('%', #{bo.anchorName}, '%')


    JOIN tb_user u ON av.user_id = u.id and (u.nick_name like CONCAT('%', #{bo.userName}, '%') or u.username
    like CONCAT('%', #{bo.userName}, '%') or u.phone LIKE CONCAT('%', #{bo.userName}, '%'))


    join tb_user_details ud on av.user_id = ud.user_id and ud.sale_id = #{bo.userSalesID}



    join tb_anchor_url_user auu on av.sec_uid = auu.anchor_url_sec_uid and av.user_id = auu.user_id and
    auu.is_deleted = 0 and auu.account_type = #{bo.accountType}

WHERE
av.is_deleted = 0
and av.duration >= 60
and av.analysis_status = 2

    and av.video_name like CONCAT('%', #{bo.videoName}, '%')



    and av.user_id = #{bo.userId}



    and av.create_date BETWEEN #{bo.startTime} and #{bo.endTime}



    and av.video_id = #{bo.videoId}



    and av.trade_id = #{bo.tradeId}



    AND av.user_id IN (

        #{item}

    )



    AND av.tenant_id IN (

        #{item}

    )


order by av.id desc

SELECT tenant_id AS tenantId, sec_uid AS secUid, COUNT(*) AS analysisCount, MIN(analysis_time) AS firstAnalyzedDate, MAX(analysis_time) AS lastAnalyzedDate FROM tb_anchor_video WHERE tenant_id IN
#{tid}
AND is_deleted = 0 AND analysis_status = 2
AND analysis_time >= #{startDate}
AND analysis_time < #{endDate}
GROUP BY tenant_id, sec_uid
